import { useEffect, useState } from "react";

export default function AdminPage() {
  const [orders, setOrders] = useState([]);
  const [menu, setMenu] = useState([]);
  const [history, setHistory] = useState([]);
  const [activeTab, setActiveTab] = useState("status");
  const [newItem, setNewItem] = useState({ category: "", name: "", price: "" });
  const [theme, setTheme] = useState("dark");
  const [buttonColor, setButtonColor] = useState("#2563eb");
  const [textColor, setTextColor] = useState("#ffffff");
  const [font, setFont] = useState("inter");

  useEffect(() => {
    const allOrders = JSON.parse(localStorage.getItem("allOrders") || "[]");
    setOrders(allOrders.filter((o) => o.status !== "Fertig"));
    setHistory(allOrders.filter((o) => o.status === "Fertig"));
    setMenu(JSON.parse(localStorage.getItem("menuData") || "[]"));
    setTheme(localStorage.getItem("theme") || "dark");
    setButtonColor(localStorage.getItem("buttonColor") || "#2563eb");
    setTextColor(localStorage.getItem("textColor") || "#ffffff");
    setFont(localStorage.getItem("font") || "inter");

    const interval = setInterval(() => {
      const updatedOrders = JSON.parse(localStorage.getItem("allOrders") || "[]");
      setOrders(updatedOrders.filter((o) => o.status !== "Fertig"));
      setHistory(updatedOrders.filter((o) => o.status === "Fertig"));
    }, 3000);

    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    localStorage.setItem("menuData", JSON.stringify(menu));
  }, [menu]);

  useEffect(() => {
    localStorage.setItem("theme", theme);
    localStorage.setItem("buttonColor", buttonColor);
    localStorage.setItem("textColor", textColor);
    localStorage.setItem("font", font);
  }, [theme, buttonColor, textColor, font]);

  const updateOrderStatus = (index, status) => {
    const allOrders = JSON.parse(localStorage.getItem("allOrders") || "[]");
    const order = allOrders.find((_, i) => i === index);
    if (order) {
      order.status = status;
      localStorage.setItem("allOrders", JSON.stringify(allOrders));
      setOrders(allOrders.filter((o) => o.status !== "Fertig"));
      setHistory(allOrders.filter((o) => o.status === "Fertig"));
    }
  };

  const deleteOrder = (index) => {
    const allOrders = JSON.parse(localStorage.getItem("allOrders") || "[]");
    allOrders.splice(index, 1);
    localStorage.setItem("allOrders", JSON.stringify(allOrders));
    setOrders(allOrders.filter((o) => o.status !== "Fertig"));
    setHistory(allOrders.filter((o) => o.status === "Fertig"));
  };

  const timeSince = (dateString) => {
    const seconds = Math.floor((new Date() - new Date(dateString)) / 1000);
    const minutes = Math.floor(seconds / 60);
    return minutes < 1 ? "gerade eben" : `vor ${minutes} Min.`;
  };

  const updateAvailability = (catIndex, itemIndex) => {
    const updated = [...menu];
    updated[catIndex].items[itemIndex].available = !updated[catIndex].items[itemIndex].available;
    setMenu(updated);
  };

  const deleteItem = (catIndex, itemIndex) => {
    const updated = [...menu];
    updated[catIndex].items.splice(itemIndex, 1);
    setMenu(updated);
  };

  const deleteCategory = (catIndex) => {
    const updated = [...menu];
    updated.splice(catIndex, 1);
    setMenu(updated);
  };

  const addItem = () => {
    if (!newItem.category || !newItem.name || !newItem.price) return;
    const updated = [...menu];
    const categoryIndex = updated.findIndex((c) => c.category === newItem.category);
    const newEntry = {
      name: newItem.name,
      price: parseFloat(newItem.price),
      available: true,
    };
    if (categoryIndex >= 0) {
      updated[categoryIndex].items.push(newEntry);
    } else {
      updated.push({ category: newItem.category, items: [newEntry] });
    }
    setMenu(updated);
    setNewItem({ category: "", name: "", price: "" });
  };

  const allItemsSold = history.flatMap((order) => order.items);
  const itemCounts = {};
  allItemsSold.forEach((item) => {
    const key = item.name;
    if (!itemCounts[key]) itemCounts[key] = 0;
    itemCounts[key] += item.quantity || 1;
  });
  const sortedItems = Object.entries(itemCounts).sort((a, b) => b[1] - a[1]).slice(0, 5);
  const totalRevenue = allItemsSold.reduce((sum, i) => sum + i.price * (i.quantity || 1), 0);
  const avgOrderValue = history.length > 0 ? totalRevenue / history.length : 0;

  return (
    <div className="min-h-screen p-6 font-sans">
      <div className="flex gap-3 mb-6">
        {["status", "history", "menu", "design", "report"].map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className={`px-4 py-2 rounded ${
              activeTab === tab ? "bg-blue-700 text-white" : "bg-gray-300 text-black"
            }`}
          >
            {tab === "status" && "Bestellungen"}
            {tab === "history" && "Historie"}
            {tab === "menu" && "Speisekarte bearbeiten"}
            {tab === "design" && "Design"}
            {tab === "report" && "Auswertung"}
          </button>
        ))}
      </div>

      {activeTab === "status" && (
        <div>
          <h2 className="text-2xl font-bold mb-4">Bestellungen</h2>
          {orders.length === 0 ? (
            <p>Keine offenen Bestellungen.</p>
          ) : (
            orders.map((order, index) => (
              <div key={index} className="border p-4 mb-4 rounded bg-gray-800 text-white">
                <p className="mb-1">Tisch: {order.tableNumber} – <span className="text-sm">{timeSince(order.created)}</span></p>
                <ul className="mb-2 list-disc pl-6">
                  {order.items.map((item, i) => (
                    <li key={i}>{item.quantity || 1}× {item.name} – {(item.price * (item.quantity || 1)).toFixed(2)} €</li>
                  ))}
                </ul>
                <p>Status: {order.status}</p>
                <div className="mt-2 flex gap-2">
                  {order.status === "Ausstehend" && (
                    <button onClick={() => updateOrderStatus(index, "In Zubereitung")} className="bg-yellow-500 px-3 py-1 rounded">
                      In Zubereitung
                    </button>
                  )}
                  {order.status === "In Zubereitung" && (
                    <button onClick={() => updateOrderStatus(index, "Fertig")} className="bg-green-600 px-3 py-1 rounded">
                      Fertig
                    </button>
                  )}
                  <button onClick={() => deleteOrder(index)} className="bg-red-600 px-3 py-1 rounded">
                    Bestellung löschen
                  </button>
                </div>
              </div>
            ))
          )}
        </div>
      )}

      {activeTab === "history" && (
        <div>
          <h2 className="text-2xl font-bold mb-4">Bestellhistorie</h2>
          {history.map((order, index) => (
            <div key={index} className="border p-4 mb-4 rounded bg-gray-100 text-black">
              <p className="mb-1">Tisch: {order.tableNumber}</p>
              <ul className="mb-2 list-disc pl-6">
                {order.items.map((item, i) => (
                  <li key={i}>{item.quantity || 1}× {item.name} – {(item.price * (item.quantity || 1)).toFixed(2)} €</li>
                ))}
              </ul>
              <p>Status: {order.status}</p>
            </div>
          ))}
        </div>
      )}

      {activeTab === "menu" && (
        <div>
          <h2 className="text-2xl font-bold mb-4">Speisekarte bearbeiten</h2>
          {menu.map((cat, catIndex) => (
            <div key={catIndex} className="mb-6">
              <div className="flex justify-between items-center mb-1">
                <h3 className="text-xl font-semibold">{cat.category}</h3>
                <button
                  onClick={() => deleteCategory(catIndex)}
                  className="text-sm text-red-500 hover:text-red-700"
                >
                  Kategorie löschen
                </button>
              </div>
              {cat.items.map((item, itemIndex) => (
                <div key={itemIndex} className="flex items-center gap-3 mb-2 bg-gray-800 p-2 rounded text-white">
                  <span className="w-48">{item.name}</span>
                  <input
                    type="number"
                    value={item.price}
                    onChange={(e) => {
                      const updated = [...menu];
                      updated[catIndex].items[itemIndex].price = parseFloat(e.target.value);
                      setMenu(updated);
                    }}
                    className="w-24 px-2 py-1 rounded text-black"
                  />
                  <label className="flex items-center ml-4">
                    <input
                      type="checkbox"
                      checked={item.available}
                      onChange={() => updateAvailability(catIndex, itemIndex)}
                      className="mr-2"
                    />
                    verfügbar
                  </label>
                  <button
                    onClick={() => deleteItem(catIndex, itemIndex)}
                    className="ml-auto bg-red-600 hover:bg-red-700 px-3 py-1 rounded text-sm"
                  >
                    Löschen
                  </button>
                </div>
              ))}
            </div>
          ))}
          <div className="mt-6">
            <h3 className="text-lg font-semibold mb-2">Neuen Artikel hinzufügen</h3>
            <div className="flex flex-col md:flex-row gap-2">
              <input className="p-2 rounded text-black" placeholder="Kategorie" value={newItem.category} onChange={(e) => setNewItem({ ...newItem, category: e.target.value })} />
              <input className="p-2 rounded text-black" placeholder="Name" value={newItem.name} onChange={(e) => setNewItem({ ...newItem, name: e.target.value })} />
              <input className="p-2 rounded text-black" placeholder="Preis" type="number" value={newItem.price} onChange={(e) => setNewItem({ ...newItem, price: e.target.value })} />
              <button onClick={addItem} className="bg-green-600 hover:bg-green-700 px-4 py-2 rounded text-white">Hinzufügen</button>
            </div>
          </div>
        </div>
      )}

      {activeTab === "design" && (
        <div>
          <h2 className="text-2xl font-bold mb-4">Design ändern</h2>
          <h3 className="text-lg font-semibold mb-2">Theme</h3>
          <div className="flex flex-wrap gap-2 mb-4">
            {["dark", "light", "blue", "green", "techy", "edel", "minimalistisch", "classic", "elegant", "neon"].map((t) => (
              <button key={t} onClick={() => setTheme(t)} className={`px-3 py-2 rounded ${theme === t ? "bg-green-600 text-white" : "bg-gray-300 text-black"}`}>
                {t}
              </button>
            ))}
          </div>
          <h3 className="text-lg font-semibold mb-2">Button-Farbe</h3>
          <input type="color" value={buttonColor} onChange={(e) => setButtonColor(e.target.value)} className="mb-4" />
          <h3 className="text-lg font-semibold mb-2">Textfarbe</h3>
          <input type="color" value={textColor} onChange={(e) => setTextColor(e.target.value)} className="mb-4" />
          <h3 className="text-lg font-semibold mb-2">Schriftart</h3>
          <select value={font} onChange={(e) => setFont(e.target.value)} className="p-2 rounded text-black">
            {["inter", "roboto", "arial", "verdana", "tahoma", "georgia", "times", "courier", "comic", "montserrat", "opensans", "ubuntu", "lato", "notosans", "ptserif", "raleway", "sourcecode", "playfair", "merriweather", "baskerville"].map((f) => (
              <option key={f} value={f}>{f}</option>
            ))}
          </select>
        </div>
      )}

      {activeTab === "report" && (
        <div>
          <h2 className="text-2xl font-bold mb-4">Auswertung</h2>
          <p className="mb-2"><strong>Gesamtumsatz:</strong> {totalRevenue.toFixed(2)} €</p>
          <p className="mb-2"><strong>Ø Bestellwert:</strong> {avgOrderValue.toFixed(2)} €</p>
          <h3 className="text-lg font-semibold mt-4 mb-2">Top 5 Artikel</h3>
          <ul className="list-disc pl-6">
            {sortedItems.map(([name, count], i) => (
              <li key={i}>{name} – {count}× verkauft</li>
            ))}
          </ul>
        </div>
      )}
    </div>
  );
}
